import os
import subprocess
import re
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Configuration
UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}
MAX_FILENAME_LEN = 255

def sanitize_filename(filename):
    """Remove directory traversal attempts but preserve the filename structure."""
    # Strip path separators to prevent directory traversal
    filename = filename.replace('/', '').replace('\\', '')
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Limit length
    return filename[:MAX_FILENAME_LEN]

def get_extension(filename):
    """Extract file extension."""
    if '.' in filename:
        return filename.rsplit('.', 1)[1].lower()
    return ''

@app.route('/api/files/convert', methods=['POST'])
def convert_file():
    """Convert uploaded file to a target format using ImageMagick."""
    if 'file' not in request.files:
        abort(400, 'No file provided')

    uploaded = request.files['file']
    target_format = request.form.get('format', 'png')

    # Validate target format
    if target_format not in ('png', 'jpg', 'pdf', 'gif', 'webp'):
        abort(400, 'Unsupported target format')

    original_filename = sanitize_filename(uploaded.filename)
    ext = get_extension(original_filename)

    if ext not in ALLOWED_EXTENSIONS:
        abort(400, 'File type not allowed')

    # Save uploaded file
    input_path = os.path.join(UPLOAD_DIR, original_filename)
    output_filename = original_filename.rsplit('.', 1)[0] + '.' + target_format
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    uploaded.save(input_path)

    # Perform conversion using ImageMagick
    # The density and quality flags ensure good output
    cmd = f'convert -density 150 -quality 90 {input_path} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            app.logger.error(f'Conversion failed: {result.stderr.decode()}')
            abort(500, 'Conversion failed')
    except subprocess.TimeoutExpired:
        abort(504, 'Conversion timed out')
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

    return jsonify({
        'status': 'success',
        'output': output_filename,
        'download_url': f'/api/files/download/{output_filename}'
    })

@app.route('/api/files/metadata', methods=['POST'])
def file_metadata():
    """Extract metadata from uploaded file using exiftool."""
    if 'file' not in request.files:
        abort(400, 'No file provided')

    uploaded = request.files['file']
    original_filename = sanitize_filename(uploaded.filename)
    ext = get_extension(original_filename)

    if ext not in ALLOWED_EXTENSIONS:
        abort(400, 'File type not allowed')

    input_path = os.path.join(UPLOAD_DIR, original_filename)
    uploaded.save(input_path)

    try:
        result = subprocess.run(
            ['exiftool', '-json', input_path],
            capture_output=True,
            timeout=10
        )
        metadata = result.stdout.decode()
    except subprocess.TimeoutExpired:
        metadata = '{}'
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

    return jsonify({'metadata': metadata})

@app.route('/api/files/download/<filename>')
def download_file(filename):
    """Serve converted files."""
    safe_name = sanitize_filename(filename)
    filepath = os.path.join(UPLOAD_DIR, safe_name)
    if not os.path.exists(filepath):
        abort(404)
    from flask import send_file
    return send_file(filepath)

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
